            />

            <div class="search-box__actions">
                <!-- 发送中按钮 -->
                <template v-if="loading">
                    <button
                        type="button"
                        class="search-box__button search-box__button--loading"
                        disabled
                    >
                        <img
                            src="@/assets/images/ai/ppt/loading-white.svg?import=url" alt="loading icon"
                            class="loading-icon"
                        >
                    </button>
                </template>


                <template v-else>
                    <!-- 禁用态 -->
                    <template v-if="!canSend || disabled">
                        <search-resend-icon v-if="props.type === InputType.RESEND" disabled/>
                        <button
                            v-else-if="props.scene !== SceneType.TEMPLATE"
                            type="button"
                            class="search-box__button search-box__send-button"
                            @click="handleSend($event, 'next_step')"
                        >
                            <send-btn-star-icon/>
                            <span>{{ $t('pptEditor.aiEdit.continue') }}</span>
                        </button>
                    </template>
                    <template v-else-if="props.type === InputType.RESEND">
                        <!-- 可发送态 -->
                        <el-popover
                            placement="top"
                            trigger="hover"
                            :show-after="100"
                            :hide-after="100"
                            popper-class="custom-action-popover"
                        >
                            <template #reference>
                                <search-resend-icon @click="handleSend"/>
                            </template>
                            <div class="popover-content">
                                <span>
                                    {{ $t('chat.bubble.actions.regenerate') }}
                                </span>
                            </div>
                        </el-popover>
                    </template>
                    <template v-else>
                        <!-- 可发送态 -->
                        <button
                            v-if="props.scene !== SceneType.TEMPLATE"
                            type="button"
                            class="search-box__button search-box__send-button"
                            @click="handleSend($event, 'next_step')"
                        >
                            <send-btn-star-icon/>
                            <span>{{ $t('pptEditor.aiEdit.continue') }}</span>
                        </button>
                    </template>
                </template>
            </div>
        </div>
        <presentation-option ref="options" :class="{ 'is-visible': shouldDisplaySettingPanel }"/>
        <button
            v-if="props.scene === SceneType.TEMPLATE"
            type="button"
            class="search-box__button search-box__send-button"
            :class="{ 'disable': pptMode === PPT_MODE.IMPORT_FILE && uploadStatus !== 'success' }"
            @click="handleSend"
        >
            <send-btn-star-icon/>
            <span>{{ $t('pptEditor.aiEdit.continue') }}</span>
        </button>
        <el-popconfirm
            v-model:visible="popconfirmVisible"
            popper-class="custom-action-popconfirm"
            placement="bottom"
            width="339px"
            trigger="click"
            :confirm-button-text="$t('home.tera_ai.ai_presentation_maker.switch_mode')"
            :cancel-button-text="$t('home.index.deleteHistory.cancel')"
            :title="$t('home.tera_ai.ai_presentation_maker.switch_to_paste')"
            :hide-icon="true"
            :hide-after="0"
            :auto-close="20000"
            @confirm="oneLineOverLimitHandler(true)"
            @cancel="oneLineOverLimitHandler(false)"
        >
            <template #reference>
                <div ref="popconfirmRef" class="custom-action-popconfirm__btn"></div>
            </template>
        </el-popconfirm>
    </div>
</template>

<script setup lang="ts">
import { type pptSettings } from '@/base/api/ppt';
import presentationOption from '@/views/ai-home/components/main-content/ai-ppt/component/presentation-options.vue';
import SendBtnStarIcon from '@/assets/images/ai/ppt/ppt-send-btn-star.svg?component';
import { ref, computed, watch, nextTick, onMounted, onUnmounted, toRef } from 'vue';
import SearchToolbar from './search-toolbar.vue';
import FileUploadCore from '@/views/ai-home/components/main-content/file-upload-core.vue';
import { SEARCH_INPUT, CHAT_MODE } from '@/base/constant/chat';
import { useAIHomeStore } from '@/stores/aiHome';
import { storeToRefs } from 'pinia';
import { useLoginCheckHook } from '@/base/utils/commonFun/withLoginCheck';
import { pendingMessagesDB } from '@/base/utils/db/pendingMessages';
import { useLoginStore } from '@baidu/web-card-v2';
import { ElPopover, ElPopconfirm } from 'element-plus';
import { googleTrack, writeLog } from '@/base/utils/analyze';
import { useRoute } from 'vue-router';
import eventBus from '@/base/utils/eventBus';
import { useChatInput } from '../../chat-hooks/ppt/chat-input';
import { SET_INPUT_VALUE } from './search-input-constants';
import { InputType, SceneType } from './constant';
import SearchResendIcon from './search-resend-btn.vue';
import { TeraMessage } from '@/components/message/index.vue';
import { useI18n } from 'vue-i18n';
import { getQueryVariable } from '@baidu/terabox-helper';
import { PPT_MODE } from './constant';
import type { UploadingStatus } from '@/base/api/typings/chat';
import { PPT_SCENE } from '@/stores/aiHome';
const options = ref<InstanceType<typeof presentationOption> | null>(null);
interface Props {
    // 输入建议列表
    suggestions?: string[]
    // 最大字数限制
    maxWords?: number
    // 组件类型,可选InputType
    type?: InputType
    // 是否加载中
    loading?: boolean
    // 是否正在生成PPT
    pptGenerating?: boolean
    // 是否禁用
    disabled?: boolean
    // 是否启用语言选择
    enableLanguage?: boolean
    // 是否显示选项
    enableOption?: boolean
    // 是否启用知识库选择
    enableLibrary?: boolean
    // 是否启用字数选择
    enableWordCount?: boolean
    // 是否启用页数选择
    enableSlideCount?: boolean
    // 上传模式,可选'image'或'file'
    uploadMode?: '' | 'image' | 'file'
    // 输入框宽度
    width?: string | number
    // 聊天模式
    mode?: CHAT_MODE,
    // 引入场景，UI样式区别
    scene?: string,
    from?: string;
    // 输入框文本值
    modelValue?: string
}

const props = withDefaults(defineProps<Props>(), {
    maxWords: 20000, // 默认20000字
    type: InputType.CHAT,
    loading: false,
    disabled: false,
    enableLanguage: false,
    enableOption: false,
    enableLibrary: false,
    enableWordCount: false,
    enableSlideCount: false,
    uploadMode: '',
    width: '100%',
    mode: CHAT_MODE.AI_HOME,
    scene: 'default',
    modelValue: '',
});
const isLandingPage = props.from === 'ai-ppt-landing-page';
const showKeywordTips = computed(() => isLandingPage && pptMode.value === PPT_MODE.ONE_LINE);
const { withLoginCheck, setLoginCallback, getLoginCallbackSig } = useLoginCheckHook();
const isSettingsButtonClicked = ref(false);
const emit = defineEmits<{
    (e: 'search', value: string, regenerateIndex: any, isResend: any, fileInfo: any, pptSettings: any): void
    (e: 'input', value: string): void
    (e: 'focus'): void
    (e: 'blur'): void
    (e: 'upload', files: File[]): void
    (e: 'stop'): void
    (e: 'input-height-change', height: number): void
}>();
const togglePresentationOptions = () => {
    isSettingsButtonClicked.value = !isSettingsButtonClicked.value;
};
const handleClickOutside = (event: MouseEvent) => {
    if (!searchBoxRef.value) {
        return;
    }

    const target = event.target as HTMLElement;

    // 检查点击是否在 搜索框内 或 下拉菜单 内
    const isClickInside = (
        searchBoxRef.value.contains(target)
        || target.closest('.base-select-dropdown') !== null
    );

    if (!isClickInside) {
        isSettingsButtonClicked.value = false;
    }
};
// 筛选项相关store
const aiHomeStore = useAIHomeStore();
const {
    selectedLanguage,
    selectedLibrary,
    selectedWordCount,
    selectedSlideCount,
    canRecoverUnsentMsg,
    pptMode,
    oneLineInputVal,
    pasteInputVal,
    pptScene,
} = storeToRefs(aiHomeStore);
const lang = selectedLanguage.value;
const sendLoading = computed(() => aiHomeStore.sendLoading);
const route = useRoute();

const showSlideCount = computed(() => props.enableSlideCount && pptMode.value === PPT_MODE.ONE_LINE);

// 输入值
const inputValue = ref('');
const uploadStatus = ref<UploadingStatus>('idle');

const searchBoxRef = ref();
const popconfirmRef = ref();
const fileUploadCoreRef = ref();
const inputFocus = ref(false);
const overLimitPendingInput = ref('');
const popconfirmVisible = ref(false);
const templateKey = 'ai_ppt_no_login_select_template_id';

const currentChatId = computed(() => (route.params?.id as string));

const shouldDisplaySettingPanel = computed(() => { // Tab是「上传文件」且上传状态不是「success」时，即使按钮被点击也不展示设置面板。
    if (!props.enableOption || !isSettingsButtonClicked.value) {
        return false;
    }

    if (pptMode.value === 'import_file') {
        return uploadStatus.value === 'success';
    }

    return true;
});
const presentationOptionStyle = computed(() => ({
    height: shouldDisplaySettingPanel.value ? '100%' : '0',
    visibility: shouldDisplaySettingPanel.value ? 'visible' : 'hidden',
    padding: shouldDisplaySettingPanel.value ? '' : 'initial',
}));
watch(() => props.modelValue, (val: string) => {
    if (props.modelValue) {
        inputValue.value = val;
        writeLog('show', 'ppt_blog_jump_keyword', { keyword: val });
    }
}, { immediate: true });
watch(() => pptMode.value, async (newVal, oldVal) => {
    isSettingsButtonClicked.value = false;
    if (currentChatId.value) {
        pptMode.value = PPT_MODE.ONE_LINE;
    } else {
        if (newVal === PPT_MODE.ONE_LINE) {
            inputValue.value = oneLineInputVal.value || '';
        } else if (newVal === PPT_MODE.PASTE) {
            inputValue.value = pasteInputVal.value || '';
        }
    }
    await nextTick();
    adjustSize();
}, { immediate: true });

watch(() => [oneLineInputVal.value, pasteInputVal.value], () => {
    if (!currentChatId.value) {
        switch (pptMode.value) {
            case PPT_MODE.ONE_LINE:
                inputValue.value = oneLineInputVal.value || '';
                break;
            case PPT_MODE.PASTE:
                inputValue.value = pasteInputVal.value || '';
                break;
            default:
                break;
        }
    }
});

watch(() => isSettingsButtonClicked.value, async (newVal, oldVal) => {
    if (newVal) {
        setTimeout(() => { // 延迟监听开始时间，避免按钮被点击时挂载监听
            document.addEventListener('click', handleClickOutside);
        });
    } else {
        document.removeEventListener('click', handleClickOutside);
    }
}, { immediate: true });

const setInputValue = (value: string) => {
    inputValue.value = value;
};
// 响应外界命令设置输入值
eventBus.on(SET_INPUT_VALUE, setInputValue);

const routeChangeHandler = ({ newId, newMode }: Record<string, string>) => {
    const newKey = newId || newMode || CHAT_MODE.AI_HOME;
    inputValue.value = aiHomeStore.unsentMsgs[newKey]?.text || '';
};

/* eslint-disable-next-line */
const { placeholder } = useChatInput(toRef(props, 'mode'), pptMode);
const googleKeyword = new URLSearchParams(window.location.search).get('keyword');
onMounted(() => {
    if (isLandingPage && googleKeyword) {
        inputValue.value = googleKeyword;
        writeLog('show', 'ppt_landing_page_keyword', { keyword: googleKeyword });
    }
    eventBus.on('route-changed', routeChangeHandler);
});

onUnmounted(() => {
    eventBus.off('route-changed', routeChangeHandler);
});

const inputRef = ref<HTMLTextAreaElement | null>(null);

const actionBarShow = computed(() => {
    return pptMode.value === PPT_MODE.ONE_LINE
        || pptMode.value === PPT_MODE.PASTE
        || (pptMode.value === PPT_MODE.IMPORT_FILE
            && uploadStatus.value === 'success');
});

// 最大字数限制 写作模式限制3000 其他20000
const maxWordsLimit = computed(() => {
    if (props.type === InputType.CHAT
        && props.mode === CHAT_MODE.AI_PPT
        && pptMode.value === PPT_MODE.ONE_LINE) {
        return 1000;
    }
    return props.maxWords;
});

// 是否显示字数限制错误
const showWordLimitError = ref(false);
const { t: $t } = useI18n();
watch(() => showWordLimitError.value, newVal => {
    if (newVal) {
        TeraMessage.error({
            message: $t('chat.input.textLimitError', {
                maxWordsLimit: maxWordsLimit.value,
            }),
        });
        showWordLimitError.value = false;
    }
});

// 计算当前字数
const currentWords = computed(() => inputValue.value.length);

// 计算是否可以发送
const canSend = computed(() => {
    // 在生成回答时不允许发送，但允许输入
    if (props.loading) {
        return false;
    }
    return (inputValue.value.trim().length > 0
        && currentWords.value <= maxWordsLimit.value)
        || (pptMode.value === PPT_MODE.IMPORT_FILE && Object.keys(aiHomeStore.fileInfo).length > 0);
});
// 获取输入框内容实际高度和宽度
const measureTextSize = (text: string) => {
    if (!searchBoxRef.value) {
        return {
            height: SEARCH_INPUT.INPUT_HEIGHT,
            width: SEARCH_INPUT.INPUT_WIDTH,
        };
    }
    const textarea = document.createElement('textarea');
    textarea.style.position = 'absolute';
    textarea.style.top = '-9999px';
    textarea.style.left = '-9999px';
    textarea.style.visibility = 'hidden';
    textarea.style.height = '1px';
    textarea.style.lineHeight = '24px';
    textarea.style.overflow = 'hidden';
    textarea.style.fontSize = '16px';
    textarea.style.letterSpacing = '0';
    textarea.style.width = 'calc(100% - 48px)';
    textarea.value = text;
    searchBoxRef.value.appendChild(textarea);
    const height = textarea.scrollHeight;

    textarea.style.width = 'auto';
    textarea.style.maxWidth = 'calc(100% - 48px)';
    textarea.style.whiteSpace = 'nowrap';
    // 24 padding + 6 buffer
    const width = textarea.scrollWidth + 24 + 6;

    return {
        height,
        width,
    };
};
// 自动调整高度
const adjustSize = async () => {
    const handler = () => {
        const textarea = inputRef.value!;
        const othersHeightSum = SEARCH_INPUT.PPT_CONTAINER_VERTICAL_PADDING
            + SEARCH_INPUT.PPT_CONTAINER_VERTICAL_GAP
            + SEARCH_INPUT.PPT_ACTION_BAR_HEIGHT;
        if (pptMode.value !== PPT_MODE.ONE_LINE) {
            textarea.style.height = `${SEARCH_INPUT.CONTAINER_HEIGHT_PPT_OTHER - othersHeightSum}px`;
            textarea.style.width = '100%';
            let containerHeight = SEARCH_INPUT.CONTAINER_HEIGHT_PPT_OTHER;
            if (isSettingsButtonClicked.value && shouldDisplaySettingPanel.value) {
                containerHeight += SEARCH_INPUT.OPTION_PANNEL;
            }
            searchBoxRef.value.style.height = `${containerHeight}px`;
            return;
        }
        textarea.style.height = `${currentChatId.value
            ? SEARCH_INPUT.OUTLINE_TEXTAREA_HEIGHT : SEARCH_INPUT.INPUT_HEIGHT}px`;
        const textareaSize = measureTextSize(inputValue.value || placeholder.value || '');
        if (showKeywordTips.value) {
            const maxWidth = textarea.parentElement!.offsetWidth;
            textarea.style.width = `${Math.min(maxWidth, textareaSize.width)}px`;
        }
        const scrollHeight = currentChatId.value && textareaSize.height <= SEARCH_INPUT.OUTLINE_TEXTAREA_HEIGHT
            ? textareaSize.height
            : textareaSize.height + 24;
        // 内容为空恢复默认状态
        if (!textarea.value.trim()) {
            let containerHeight = currentChatId.value
                ? SEARCH_INPUT.OUTLINE_INPUT_HEIGHT
                : SEARCH_INPUT.CONTAINER_HEIGHT_PPT_ONELINE;
            if (isSettingsButtonClicked.value) {
                containerHeight += SEARCH_INPUT.OPTION_PANNEL;
            }
            searchBoxRef.value.style.height = `${containerHeight}px`;
            emit('input-height-change', containerHeight);
            return;
        }
        // 超过一行扩展索索栏
        const maxTextHeight = SEARCH_INPUT.MAX_CONTAINER_HEIGHT_PPT_ONELINE - othersHeightSum;
        const realTextHeight = Math.min(scrollHeight, maxTextHeight);
        const keywordTipsHeight = 28;
        let realHeight = realTextHeight
            + SEARCH_INPUT.PPT_CONTAINER_VERTICAL_PADDING
            + SEARCH_INPUT.PPT_CONTAINER_VERTICAL_GAP
            + SEARCH_INPUT.PPT_ACTION_BAR_HEIGHT
            + SEARCH_INPUT.SUGGESTIONS_RESERVE_HEIGHT
            + (showKeywordTips.value ? keywordTipsHeight : 0);
        if (isSettingsButtonClicked.value) {
            realHeight += SEARCH_INPUT.OPTION_PANNEL;
        }
        textarea.style.height = `${realTextHeight}px`;
        searchBoxRef.value.style.height = `${realHeight}px`;
        emit('input-height-change', realHeight);
    };
    if (inputRef.value) {
        handler();
    } else {
        await nextTick();
        handler();
    }
};

const handleOverLimitPopover = () => {
    if (currentChatId.value) {
        return;
    }
    if (!popconfirmVisible.value) {
        const textareaHeight = inputRef.value?.offsetHeight || 0;
        if (textareaHeight >= SEARCH_INPUT.MAX_TEXT_ONELINE_HEIGHT) {
            pptMode.value === PPT_MODE.ONE_LINE && popconfirmRef.value?.click();
        } else {
            setTimeout(() => {
                pptMode.value === PPT_MODE.ONE_LINE && popconfirmRef.value?.click();
            }, 300);
        }
    }
};

watch([inputValue, placeholder], () => {
    nextTick(() => {
        adjustSize();
    });

    // 检查字数限制
    if (currentWords.value > maxWordsLimit.value) {
        overLimitPendingInput.value = inputValue.value;
        showWordLimitError.value = true;
        // 截断超出的内容
        inputValue.value = inputValue.value.slice(0, maxWordsLimit.value);
        handleOverLimitPopover();
    }
    if (!currentChatId.value) {
        if (pptMode.value === PPT_MODE.ONE_LINE) {
            oneLineInputVal.value = inputValue.value || '';
        } else if (pptMode.value === PPT_MODE.PASTE) {
            pasteInputVal.value = inputValue.value || '';
        }
    }
});

// 处理输入
const handleInput = () => {
    // 二次检查字数限制
    if (inputValue.value.length > maxWordsLimit.value) {
        inputValue.value = inputValue.value.slice(0, maxWordsLimit.value);
        showWordLimitError.value = true;
        // 兼容汉语系输入法超长不触发inputValue watch问题
        handleOverLimitPopover();
    }

    emit('input', inputValue.value);
    aiHomeStore.updateUnsentMsgs({
        id: (route.params?.id || route.meta?.mode || CHAT_MODE.AI_HOME) as string,
        text: inputValue.value,
    });
};
const loginStore = useLoginStore();

const handleGoogleTrack = () => {
    // 添加 Google Analytics 跟踪
    let trackType = '';
    switch (props.mode) {
        case CHAT_MODE.AI_ASSISTANT:
            trackType = 'ai_assistant';
            break;
        case CHAT_MODE.AI_ESSAY_WRITER:
            trackType = 'ai_essay_writer';
            break;
        case CHAT_MODE.AI_PPT:
            trackType = 'ai_ppt';
            break;
        case CHAT_MODE.SMART_PARAPHRASE:
            trackType = 'ai_paraphrase';
            break;
        default:
            trackType = 'ai_default';
    }
    googleTrack('ai_input_send', {
        type: trackType,
    });
    googleTrack('level_up', {
        type: trackType,
        character: getQueryVariable('ad_material_source'),
    });
};
const autoSendPendingMsg = async () => {
    const pendingMessage = await pendingMessagesDB.getPendingMessage();
    await aiHomeStore.pureHandleCount();
    if (pendingMessage) {
        // 恢复内容
        inputValue.value = pendingMessage.content;
        if (pendingMessage.otherParams?.isGoogleKeyword) {
            writeLog('show', 'ppt_landing_page_keyword_send', { keyword: pendingMessage.content });
        }
        if (pendingMessage.filters) {
            if (pendingMessage.filters.language) {
                selectedLanguage.value = pendingMessage.filters.language;
            }
            if (pendingMessage.filters.library) {
                selectedLibrary.value = pendingMessage.filters.library;
            }
            if (pendingMessage.filters.wordCount) {
                selectedWordCount.value = pendingMessage.filters.wordCount;
            }
            if (pendingMessage.filters.slideCount) {
                selectedSlideCount.value = pendingMessage.filters.slideCount;
            }
        }
        const allPptModes = Object.values(PPT_MODE);
        if (pendingMessage.inputMode && allPptModes.includes(pendingMessage.inputMode)) {
            pptMode.value = pendingMessage.inputMode;
        }
        // 自动发送未发送的消息
        handleSend();
    }
};
// 处理搜索
const handleSearch = async () => {
    // 清空暂存的消息
    pendingMessagesDB.clearPendingMessages();
    // 如果未登录，保存消息到 IndexedDB
    if (!loginStore.uk) {
        if (props.scene === SceneType.TEMPLATE && aiHomeStore.pptTemplateId !== -1) {
            sessionStorage.setItem(templateKey, String(aiHomeStore.pptTemplateId));
        } else {
            sessionStorage.removeItem(templateKey);
        }

        // 标记是否为谷歌搜索关键词
        let isGoogleKeyword = false;
        if (isLandingPage && googleKeyword === inputValue.value) {
            isGoogleKeyword = true;
        }
        await pendingMessagesDB.savePendingMessage(
            inputValue.value,
            props.mode as CHAT_MODE,
            {
                language: selectedLanguage.value,
                library: selectedLibrary.value,
                wordCount: selectedWordCount.value,
                slideCount: selectedSlideCount.value,
            },
            pptMode.value,
            {
                isGoogleKeyword,
            }
        );
        if (pptMode.value === PPT_MODE.IMPORT_FILE) {
            withLoginCheck(props.mode, 'upload');
        } else if (pptMode.value === PPT_MODE.PASTE) {
            withLoginCheck(props.mode, 'paste');
        } else {
            withLoginCheck(props.mode, 'send');
        }
    } else {
        handleGoogleTrack();
        if (props.scene !== SceneType.TEMPLATE) {
            aiHomeStore.pptTemplateId = -1; // 如果不是从模版详情页发送的需要清空id
        }
        // 如果有输入文本，触发搜索
        if (inputValue.value.trim()) {
            if (!currentChatId.value) {
                if (pptMode.value === PPT_MODE.ONE_LINE) {
                    pptScene.value = PPT_SCENE.ONE_LINE;
                } else if (pptMode.value === PPT_MODE.PASTE) {
                    pptScene.value = PPT_SCENE.PASTE;
                }
            }
            const searchVal = inputValue.value;
            if (props.type === InputType.CHAT) {
                adjustSize();
            }
            emit('search', searchVal, undefined, undefined, false, options.value?.getSettings() ?? {});
        }
    }
};

const handleSend = (event?: MouseEvent, action?: string) => {
    if (action === 'next_step') {
        writeLog('action', 'ppt_input_next_step', {
            mode: pptMode.value,
        });
        switch (pptMode.value) {
            case PPT_MODE.ONE_LINE:
                googleTrack('level_end', {
                    character: getQueryVariable('ad_material_source'),
                });
                break;
            case PPT_MODE.PASTE:
                googleTrack('join_group', {
                    character: getQueryVariable('ad_material_source'),
                });
                break;
            case PPT_MODE.IMPORT_FILE:
                break;
            default:
                break;
        }
    }
    if (pptMode.value === PPT_MODE.IMPORT_FILE) {
        // 未上传成功不能点击
        if (uploadStatus.value !== 'success') {
            return;
        }
        if (fileUploadCoreRef.value) {
            !currentChatId.value && (pptScene.value = PPT_SCENE.IMPORT_FILE);
            fileUploadCoreRef.value.handleSubmit(options.value?.getSettings() ?? {});
        }
        return;
    }
    if (!canSend.value || props.disabled) {
        TeraMessage.error({
            message: $t('home.tera_ai.ai_presentation_maker.input_empty'),
        });
        return;
    }
    handleSearch();
    const id = route.params?.id || route.meta?.mode || CHAT_MODE.AI_HOME;
    aiHomeStore.updateUnsentMsgs({
        id: id as string,
        text: '',
    });
    if (id === CHAT_MODE.AI_HOME) {
        // 首页new chat发消息时，转到assistant对话后不恢复未发送数据，避免和assistant新对话框冲突
        canRecoverUnsentMsg.value = false;
    }
};
setLoginCallback(() => {
    const { fromValueSuffix } = getLoginCallbackSig();
    if (fromValueSuffix === 'send' || fromValueSuffix === 'paste') {
        autoSendPendingMsg();
    } else if (fromValueSuffix === 'upload') {
        pptMode.value = PPT_MODE.IMPORT_FILE;
    }
});

// 处理焦点
const handleFocus = () => {
    inputFocus.value = true;
    emit('focus');
};
const handleBlur = () => {
    inputFocus.value = false;
    emit('blur');
};

const currentMode = computed(() => Number(route.meta.mode) || CHAT_MODE.AI_HOME);
// 计算是否显示工具栏
const showToolbar = computed(() => {
    return currentMode.value !== CHAT_MODE.AI_HOME
        && (props.enableLanguage
            || props.enableLibrary
            || props.enableWordCount
            || props.enableSlideCount
            || aiHomeStore.showRemainCnt);
});

// 是否展开
const isExpanded = ref(false);
watch(() => [inputRef.value, inputValue.value], () => {
    nextTick(() => {
        if (!inputRef.value || !inputValue.value.trim()) {
            isExpanded.value = false;
        } else {
            isExpanded.value = inputRef.value.scrollHeight > SEARCH_INPUT.INPUT_HEIGHT + 2;
        }
    });
});
watch(isSettingsButtonClicked, (newValue, oldValue) => {
    nextTick(() => {
        adjustSize();
    });
});
const inputCssVars = {
    '--container-height': `${SEARCH_INPUT.CONTAINER_HEIGHT_PPT_ONELINE}px`,
    '--container-height-other': `${SEARCH_INPUT.CONTAINER_HEIGHT_PPT_OTHER}px`,
    '--input-height': `${SEARCH_INPUT.INPUT_HEIGHT}px`,
    '--max-height': `${SEARCH_INPUT.MAX_HEIGHT - SEARCH_INPUT.BUTTON_HEIGHT - SEARCH_INPUT.BOTTOM_GAP}px`,
    '--expanded-padding': `${SEARCH_INPUT.BUTTON_HEIGHT + SEARCH_INPUT.BOTTOM_GAP}px`,
    '--outline-input-height': `${SEARCH_INPUT.OUTLINE_INPUT_HEIGHT}px`,
    '--outline-textarea-height': `${SEARCH_INPUT.OUTLINE_TEXTAREA_HEIGHT}px`,
};

// 输入法状态
const isComposing = ref(false);

// 输入键入
const handleCompositionStart = () => {
    isComposing.value = true;
};

// 输入结束
const handleCompositionEnd = () => {
    isComposing.value = false;
};

const handleEnterKey = (e: KeyboardEvent) => {
    // 输入法态，不处理回车事件
    if (isComposing.value) {
        return;
    }

    if (e.shiftKey) {
        // shift+enter 换行
        return;
    }
    e.preventDefault();
    handleSend();

};

const handleUploadStatusChange = (status: UploadingStatus) => {
    uploadStatus.value = status;
};

const oneLineOverLimitHandler = (confirm: boolean) => {
    if (confirm) {
        pasteInputVal.value = overLimitPendingInput.value;
        oneLineInputVal.value = '';
        aiHomeStore.updatePptMode(PPT_MODE.PASTE);
    }
    overLimitPendingInput.value = '';
};

const handleUpdateUploadLanguge = (lang: string) => {
    aiHomeStore.updateSelectedLanguage(lang);
};

// const handleStop = () => {
//     if (props.pptGenerating) {
//         return;
//     }
//     emit('stop');
// };

onUnmounted(() => {
    document.removeEventListener('click', handleClickOutside);
});
</script>

