<script setup lang="ts">
import { TeraMessage } from '@/components/message/index.vue';
import { ref, computed, defineEmits, nextTick, watch, onMounted } from 'vue';
import { useI18n } from 'vue-i18n';

const { t: $t } = useI18n();
interface Props {
    placeholder?: string;
    modelValue?: string;
    maxWords?: number;
    disabled?: boolean;
    minRows?: number;
    maxRows?: number;
}

const props = withDefaults(defineProps<Props>(), {
    placeholder: '',
    modelValue: '',
    maxWords: 10000, // 默认10000字
    disabled: false,
    minRows: 4,
    maxRows: 6,
});

const emit = defineEmits<{
    (e: 'focus'): void;
    (e: 'blur'): void;
    (e: 'update:modelValue', value: string): void;
    (e: 'keydownEnter', value: KeyboardEvent): void;
    (e: 'input', value: string): void;
    (e: 'compositionstart'): void;
    (e: 'compositionend'): void;
}>();

// 输入法状态
const isComposing = ref(false);

const handleFocus = () => emit('focus');
const handleBlur = () => emit('blur');
const handleEnterKey = (e: KeyboardEvent) => {
    // 输入法态，不处理回车事件
    if (isComposing.value) {
        return;
    }
    // shift+enter 换行
    if (e.shiftKey) {
        return;
    }
    e.preventDefault();
    emit('keydownEnter', e);
};
const handleInput = (e: Event) =>
    emit('input', (e.target as HTMLTextAreaElement).value);
const handleCompositionStart = () => {
    isComposing.value = true;
    emit('compositionstart');
};
const handleCompositionEnd = () => {
    isComposing.value = false;
    emit('compositionend');
};

const inputRef = ref<HTMLTextAreaElement | null>(null);
// 是否显示字数限制错误
const showWordLimitError = ref(false);

watch(() => showWordLimitError.value, newVal => {
    if (newVal) {
        // 截断超出的内容
        inputValue.value = inputValue.value.slice(0, props.maxWords);
        TeraMessage.error({
            message: $t('chat.input.textLimitError', {
                maxWordsLimit: props.maxWords,
            }),
        });
        showWordLimitError.value = false;
    }
});
const lineHeight = 31;
const adjustHeight = async () => {
    await nextTick();
    if (inputRef.value) {
        const textarea = inputRef.value;
        const minHeight = props.minRows * lineHeight;
        const maxHeight = props.maxRows * lineHeight;
        textarea.style.height = minHeight + 'px';
        const scrollHeight = textarea.scrollHeight;

        // 内容为空恢复默认状态
        if (!textarea.value.trim()) {
            textarea.style.height = minHeight + 'px';
            textareaStyle.value.height = minHeight + 'px';
            return;
        }

        // 超过一行扩展索索栏
        if (scrollHeight > minHeight + 2) {
            const newHeight = Math.min(scrollHeight, maxHeight);
            textarea.style.height = newHeight + 'px';
            textareaStyle.value.height = newHeight + 'px';
        } else {
            textarea.style.height = minHeight + 'px';
            textareaStyle.value.height = minHeight + 'px';
        }
    }
};
const textareaStyle = ref({
    height: lineHeight + 'px',
});
textareaStyle.value.height = props.minRows * lineHeight + 'px';

onMounted(() => {
    adjustHeight();
});

const inputValue = computed({
    get: () => props.modelValue,
    set: (value: string) => {
        // 检查字数限制
        if (value.length > props.maxWords) {
            showWordLimitError.value = true;
        } else {
            showWordLimitError.value = false;
        }

        emit('update:modelValue', value);
        nextTick(() => {
            adjustHeight();
        });
    },
});
</script>

